/// Version of the engine inside this library and the pinned engine reference it was built from,
/// e.g. `0.8.0 (6d2ac79e)`.
#[uniffi::export]
pub fn engine_version() -> String {
    let reference = env!("MUMCORD_ENGINE_REF");
    // A commit hash is shortened; a release tag is shown as it is.
    let is_hash = reference.len() == 40 && reference.bytes().all(|b| b.is_ascii_hexdigit());
    let short = if is_hash { &reference[..8] } else { reference };
    format!("{} ({short})", env!("MUMCORD_ENGINE_VERSION"))
}

/// Reads a `mumble://` link (`mumble://[user@]host[:port]/[channel/path]`) into the target the
/// app shows for confirmation. Nothing is saved and nothing connects.
#[uniffi::export]
pub fn parse_mumble_link(url: String) -> Result<MumbleLink, BridgeError> {
    convert::parse_mumble_link(&url)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn engine_version_names_version_and_pin() {
        let version = engine_version();
        let (number, pin) = version.split_once(" (").expect("version and pin");
        assert!(number.split('.').count() >= 3, "{version}");
        assert!(!pin.trim_end_matches(')').is_empty(), "{version}");
        assert!(env!("MUMCORD_ENGINE_REF").starts_with(pin.trim_end_matches(')')));
    }
}
